// npm i express express-session express-rate-limit bcrypt
const express = require('express');
const session = require('express-session');
const { rateLimit } = require('express-rate-limit');
const bcrypt = require('bcrypt');

const app = express();
app.use(express.json());
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
    maxAge: 1000 * 60 * 60 * 8,
  },
}));

const users = new Map(); // username -> { hash }; replace with your database.

// Compared against when the user does not exist, so response time does not reveal valid usernames.
const DUMMY_HASH = bcrypt.hashSync('dummy', 12);

// Only failed attempts count: 5 per IP per 15 minutes.
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 5,
  skipSuccessfulRequests: true,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many failed attempts. Try again later.' },
});

function credentials(req, res, next) {
  const { username, password } = req.body ?? {};
  // bcrypt silently ignores everything past 72 bytes, so reject longer passwords.
  if (typeof username !== 'string' || typeof password !== 'string' ||
      !username || password.length < 8 || Buffer.byteLength(password) > 72) {
    return res.status(400).json({ error: 'Invalid username or password format' });
  }
  next();
}

app.post('/register', credentials, async (req, res) => {
  const { username, password } = req.body;
  if (users.has(username)) return res.status(409).json({ error: 'Username taken' });
  users.set(username, { hash: await bcrypt.hash(password, 12) });
  res.status(201).json({ ok: true });
});

app.post('/login', loginLimiter, credentials, async (req, res) => {
  const { username, password } = req.body;
  const user = users.get(username);
  const ok = await bcrypt.compare(password, user ? user.hash : DUMMY_HASH);
  if (!user || !ok) return res.status(401).json({ error: 'Invalid username or password' });

  // A fresh session ID on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return res.status(500).json({ error: 'Login failed' });
    req.session.userId = username;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res) => {
  req.session.destroy(() => {
    res.clearCookie('connect.sid');
    res.json({ ok: true });
  });
});

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not logged in' });
  next();
}

app.get('/me', requireAuth, (req, res) => res.json({ username: req.session.userId }));

app.listen(3000);
```

I have not run this; it assumes Express 5, which forwards errors from async handlers (on Express 4, wrap them in try/catch).

- **Session store:** sessions live in the default in-memory store, which leaks and is lost on restart, so add a store such as `connect-redis` before production.
- **Proxy:** behind a reverse proxy, set `app.set('trust proxy', 1)`, or the rate limiter sees one IP for everyone and the secure cookie is never sent.
- **Per-account limit:** the limit is per IP only, so add a per-username counter if you need to stop attacks spread across many IPs.
